//S8: 多要素認証 (TOTP / RFC 6238) — 生成時 標準装備テンプレート
// 外部依存ゼロ (Node 標準 crypto のみ)。Google Authenticator / Microsoft
// Authenticator / 1Password 等の標準 TOTP アプリと互換 (SHA-1 / 30秒 / 6桁)。
//
// 有効化手順:
//  1) Prisma User モデルに追加:
//       totpSecret  String?              // field-crypto.ts の encryptField で暗号化保存を推奨
//       mfaEnabled  Boolean @default(false)
//       backupCodes String?              // hashBackupCode() のハッシュ JSON 配列
//  2) 設定画面: generateTotpSecret() → totpAuthUri() を QR 表示 (qrcode 等) →
//     ユーザー入力の6桁を verifyTotp() で確認できたら mfaEnabled=true
//  3) ログイン: パスワード照合成功後、mfaEnabled なら6桁入力ステップを挟む。
//     バックアップコードは verifyBackupCode() 照合・一致したら配列から除去 (単回使用)

import crypto from 'crypto';

const BASE32_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';

export function base32Encode(buf: Buffer): string {
  let bits = 0;
  let value = 0;
  let out = '';
  for (const byte of buf) {
    value = (value << 8) | byte;
    bits += 8;
    while (bits >= 5) {
      out += BASE32_ALPHABET[(value >>> (bits - 5)) & 31];
      bits -= 5;
    }
  }
  if (bits > 0) out += BASE32_ALPHABET[(value << (5 - bits)) & 31];
  return out;
}

export function base32Decode(s: string): Buffer {
  const clean = s.toUpperCase().replace(/[^A-Z2-7]/g, '');
  let bits = 0;
  let value = 0;
  const bytes: number[] = [];
  for (const ch of clean) {
    value = (value << 5) | BASE32_ALPHABET.indexOf(ch);
    bits += 5;
    if (bits >= 8) {
      bytes.push((value >>> (bits - 8)) & 0xff);
      bits -= 8;
    }
  }
  return Buffer.from(bytes);
}

/** 新規 TOTP シークレットを発行 (base32 / 既定 160bit) */
export function generateTotpSecret(byteLength = 20): string {
  return base32Encode(crypto.randomBytes(byteLength));
}

/** 指定時刻の TOTP コードを計算 (RFC 6238 / HMAC-SHA1) */
export function totpCode(
  secretBase32: string,
  atMs: number = Date.now(),
  stepSec = 30,
  digits = 6,
): string {
  const counter = Math.floor(atMs / 1000 / stepSec);
  const msg = Buffer.alloc(8);
  msg.writeBigUInt64BE(BigInt(counter));
  const hmac = crypto.createHmac('sha1', base32Decode(secretBase32)).update(msg).digest();
  const offset = hmac[hmac.length - 1] & 0x0f;
  const bin =
    ((hmac[offset] & 0x7f) << 24) |
    (hmac[offset + 1] << 16) |
    (hmac[offset + 2] << 8) |
    hmac[offset + 3];
  return (bin % 10 ** digits).toString().padStart(digits, '0');
}

/** ユーザー入力コードの検証 (前後 ±window ステップ = 時計ずれ許容 / タイミング攻撃耐性) */
export function verifyTotp(
  secretBase32: string,
  inputCode: string,
  window = 1,
  atMs: number = Date.now(),
): boolean {
  const normalized = (inputCode || '').replace(/[\s-]/g, '');
  if (!/^\d{6,8}$/.test(normalized)) return false;
  let ok = false;
  for (let w = -window; w <= window; w++) {
    const candidate = totpCode(secretBase32, atMs + w * 30_000, 30, normalized.length);
    // 一致しても走査を止めない (検証時間を一定に保つ)
    if (crypto.timingSafeEqual(Buffer.from(candidate), Buffer.from(normalized))) ok = true;
  }
  return ok;
}

/** 認証アプリ登録用 URI (QR コード化して表示する) */
export function totpAuthUri(secretBase32: string, accountName: string, issuer: string): string {
  const label = `${encodeURIComponent(issuer)}:${encodeURIComponent(accountName)}`;
  return `otpauth://totp/${label}?secret=${secretBase32}&issuer=${encodeURIComponent(issuer)}&algorithm=SHA1&digits=6&period=30`;
}

/** バックアップコード発行 (印刷・保管用 / 表示は発行時の1回のみ) */
export function generateBackupCodes(count = 10): string[] {
  return Array.from({ length: count }, () => crypto.randomBytes(5).toString('hex'));
}

/** バックアップコードはハッシュのみ DB 保存する */
export function hashBackupCode(code: string): string {
  return crypto.createHash('sha256').update(code.trim().toLowerCase()).digest('hex');
}

/** 一致したハッシュの index を返す (-1 = 不一致)。一致したら配列から除去して保存し直す (単回使用) */
export function verifyBackupCode(code: string, storedHashes: string[]): number {
  const h = hashBackupCode(code);
  return storedHashes.findIndex((x) => x === h);
}
